return (() => {
  const rows = items.map(item => item.json);
  const issuer = $('Webhook generación reporte').first().json.body.full_name

  // Get current day and full month name in Spanish (e.g., "12 octubre")
  const hoy = new Date();
  const fecha = new Intl.DateTimeFormat("es-ES", {
    day: "2-digit",
    month: "long",
    timeZone: "Etc/GMT+5" // Note: GMT+5 means UTC-5 in IANA format
  }).format(hoy);

  // Build nested structure: Secuencia -> Etapa -> Tipo totals
  const data = {};
  let grandTotal = 0;

  for (const row of rows) {
    const sec = row.Secuencia;
    const etapa = row.Etapa;
    const tipo = row.Tipo;
    const total = Number(row.Total) || 0;

    if (!data[sec]) {
      data[sec] = { etapas: {}, subtotal: 0 };
    }
    if (!data[sec].etapas[etapa]) {
      data[sec].etapas[etapa] = { tipos: { IN: 0, PG: 0 }, subtotal: 0 };
    }

    data[sec].etapas[etapa].tipos[tipo] =
      (data[sec].etapas[etapa].tipos[tipo] || 0) + total;
    data[sec].etapas[etapa].subtotal += total;
    data[sec].subtotal += total;
    grandTotal += total;
  }

  // Build plain text report
  let report = `<strong>Reportes corte ${fecha}<br><br></strong>`;

  for (const secuencia of Object.keys(data)) {
    const sec = data[secuencia];

    report += `<strong>${secuencia}<br></strong>`;
    report += `Total: ${sec.subtotal}<br>`;

    for (const etapa of Object.keys(sec.etapas)) {
      const et = sec.etapas[etapa];
      const inTotal = et.tipos.IN || 0;
      const pgTotal = et.tipos.PG || 0;
      report += `-${etapa}: ${et.subtotal} (${inTotal} IN / ${pgTotal} PG)<br>`;
    }

    report += `<br>`;
  }

  report += `<strong>Total general: ${grandTotal}<br></strong>`;
  report += `<br>Reporte solicitado por: ${issuer}`;

  return [{ json: { report } }];
})();

